// Recorre todas las publicaciones ACTIVAS del vendedor y devuelve
// un item por publicacion con: item_id, title, permalink, description.
// El token llega desde el nodo Read_token.

const entrada = $input.first().json;
const token = entrada.token || entrada.access_token || entrada.accessToken;
if (!token) {
  throw new Error('No llego el token desde Read_token. Revisa que campo devuelve (token / access_token).');
}
const auth = { Authorization: 'Bearer ' + token };

// 1) ID del vendedor
const me = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.mercadolibre.com/users/me',
  headers: auth,
  json: true,
});
const userId = me.id;

// 2) IDs de todas las publicaciones activas (paginado)
let ids = [];
let offset = 0;
const limit = 50;
while (true) {
  const search = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.mercadolibre.com/users/' + userId + '/items/search',
    qs: { status: 'active', limit: limit, offset: offset },
    headers: auth,
    json: true,
  });
  const results = (search && search.results) || [];
  ids = ids.concat(results);
  const total = (search && search.paging && search.paging.total) || 0;
  offset += limit;
  if (results.length === 0 || offset >= total || offset >= 1000) break;
}

// 3) Titulo, permalink y descripcion de cada publicacion
const out = [];
for (const id of ids) {
  let title = '';
  let permalink = '';
  let description = '';
  try {
    const item = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.mercadolibre.com/items/' + id,
      qs: { attributes: 'id,title,permalink,status' },
      headers: auth,
      json: true,
    });
    title = item.title || '';
    permalink = item.permalink || '';
  } catch (e) {}
  try {
    const desc = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.mercadolibre.com/items/' + id + '/description',
      headers: auth,
      json: true,
    });
    description = ((desc && (desc.plain_text || desc.text)) || '').trim();
  } catch (e) {}
  out.push({ json: { item_id: id, title: title, permalink: permalink, description: description } });
}

return out;
